class Solution:
    def addBinary(self, A, B):
        res = []
        carry = 0
        while A or B or carry:
            carry += (A or [0])[0] + (B or [0])[0]
            res.append(carry & 1)
            carry = carry >> 1
            A = A[1:] if A else []
            B = B[1:] if B else []
        return ''.join(map(str, res[::-1]))

    def addNegabinary(self, A, B):
        res = []
        carry = 0
        while A or B or carry:
            carry += (A or [0])[0] + (B or [0])[0]
            res.append(carry & 1)
            carry = -(carry >> 1)
            A = A[1:] if A else []
            B = B[1:] if B else []
        while len(res) > 1 and res[-1] == 0:
            res.pop()
        return ''.join(map(str, res[::-1]))

