import collections

class Solution:
    def isPossibleToCutPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        dirs = [(-1, 0), (0, -1)]

        def dfs(i: int, j: int) -> None:
            grid[i][j] = 2

        # First DFS to mark all nodes reachable from (0, 0) with value 1
        for di, dj in dirs:
            if 0 <= i + di < m and 0 <= j + dj < n and grid[i + di][j + dj] == 1:
                dfs(i + di, j + dj)

        # Second DFS to check if the path from (0, 0) to (m-1, n-1) is still valid
        dfs(m - 1, n - 1)

        dq = collections.deque([(0, 0)])
        grid[0][0] = 0
        dirs = [(1, 0), (0, 1)]

        while dq:
            l = len(dq)
            for _ in range(l):
                i, j = dq.popleft()
                if i == m - 1 and j == n - 1:
                    return False
                for di, dj in dirs:
                    if 0 <= i + di < m and 0 <= j + dj < n and grid[i + di][j + dj] == 2:
                        dq.append((i + di, j + dj))
                        grid[i + di][j + dj] = 0

        if len(dq) == 1 and dq[0] != (m - 1, n - 1):
            return True

        return True

