class Solution:
    def reverseKGroup(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:
        dummy = ListNode(0, head)
        currGroup = dummy

        while True:
            kth = self.getKth(currGroup, k)
            if not kth:
                break
            nextGroup = kth.next

            # reverse the currGroup
            prev, curr = None, currGroup.next
            while curr != nextGroup:
                tmp = curr.next
                curr.next = prev
                prev = curr
                curr = tmp

            currGroup.next, currGroup = kth, prev

        return dummy.next


    def getKth(self, node, k):
        while node and k:
            node = node.next
            k -= 1
        return node

