class Solution {
public:
    int findPeakElement(std::vector<int>& nums) {
        int n = nums.size();
        if (n == 1) {
            return 0;
        }
        if (nums[0] > nums[1]) {
            return 0;
        }
        if (nums[n - 1] > nums[n - 2]) {
            return n - 1;
        }
        int left = 1;
        int right = n - 2;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (nums[mid] > nums[mid - 1] && nums[mid] > nums[mid + 1]) {
                return mid;
            } else if (nums[mid] > nums[mid - 1]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -1;
    }
};

class Solution {
public:
    void merge(vector<int>& arr, int low, int mid, int high, int &cnt) {
        int i = low, j = mid + 1;
        int r = j;
        int c = 0;
        vector<int> v;

        while (i <= mid) {
            while (r <= high && arr[i] > (long long)2 * arr[r]) {
                c++;
                r++;
            }
            cnt += c;

            while (j <= r && arr[j] <= arr[i]) {
                v.push_back(arr[j++]);
            }
            v.push_back(arr[i++]);
        }

        while (j <= high) {
            v.push_back(arr[j++]);
        }

        for (int i = low; i <= high; i++) {
            arr[i] = v[i - low];
        }
    }

    void mergesort(vector<int>& arr, int low, int high, int &cnt) {
        if (low < high) {
            int mid = low + (high - low) / 2;
            mergesort(arr, low, mid, cnt);
            mergesort(arr, mid + 1, high, cnt);
            merge(arr, low, mid, high, cnt);
        }
    }

    int reversePairs(vector<int>& arr) {
        int cnt = 0;
        int n = arr.size();
        mergesort(arr, 0, n - 1, cnt);
        return cnt;
    }
};

