class Solution {
public:
    void bfs(int prevcolor, int row, int col, int color, vector<vector<int>>& visited, vector<vector<int>>& image) {
        // it'll ease the work
        queue<pair<int, int>> q;
        q.push({row, col});
        visited[row][col] = 1;

        while (!q.empty()) {
            int r = q.front().first;
            int c = q.front().second;
            q.pop();

            // if img is of the starting color.
            if (image[r][c] == prevcolor) 
                image[r][c] = color;

            // up
            if (r - 1 >= 0 && !visited[r - 1][c] && image[r - 1][c] == prevcolor) {
                q.push({r - 1, c});
                visited[r - 1][c] = 1;
                image[r - 1][c] = color;
            }

            // right
            if (c + 1 < image[0].size() && !visited[r][c + 1] && image[r][c + 1] == prevcolor) {
                q.push({r, c + 1});
                visited[r][c + 1] = 1;
                image[r][c + 1] = color;
            }

            // down
            if (r + 1 < image.size() && !visited[r + 1][c] && image[r + 1][c] == prevcolor) {
                q.push({r + 1, c});
                visited[r + 1][c] = 1;
                image[r + 1][c] = color;
            }

            // left
            if (c - 1 >= 0 && !visited[r][c - 1] && image[r][c - 1] == prevcolor) {
                q.push({r, c - 1});
                visited[r][c - 1] = 1;
                image[r][c - 1] = color;
            }
        }
    }

    vector<vector<int>> floodFill(vector<vector<int>>& image, int sr, int sc, int color) {
        int prevcolor = image[sr][sc];

        // visiting array.
        vector<vector<int>> visited(image.size(), vector<int>(image[0].size(), 0));

        bfs(prevcolor, sr, sc, color, visited, image);

        return image;
    }
};

class Solution {
public:
    int r[4] = {-1, 0, 1, 0};
    int c[4] = {0, 1, 0, -1};

