class Solution {
public:
    int dp[105][10005];

    int helper(int i, int n, int sum)
    {
        std::vector<int>& arr = arr_; // Use a member variable instead of a local variable

        if(sum == 0)
        {
            return 0;
        }

        if(i >= n || sum < 0)
        {
            return INT_MAX - 1000;
        }

        if(dp[i][sum] != -1)
        {
