        }

        int mini = INT_MAX;

        if(arr[i] <= sum)
        {
            mini = std::min(mini, 1 + helper(i, n, sum - arr[i]));
        }

        mini = std::min(mini, helper(i + 1, n, sum));

        return dp[i][sum] = mini;
    }

