class Solution {
public:
    vector<int> numMovesStonesII(vector<int>& stones) {
        sort(stones.begin(), stones.end());

        int N = stones.size(), low = N;
        for (int i = 0, j = 0; j < N; ++j) {
            while (stones[j] - stones[i] + 1 > N) {
                ++i;
            }
            int gap = N - (j - i + 1);
            if (gap == 1 && stones[j] - stones[i] + 1 == 1) {
                low = std::min(low, 2);
            } else {
                low = std::min(low, gap);
            }
        }

        int high = 1 + std::max((stones[N - 1] - stones[1] + 1) - N,  // Move to right most
                               (stones[N - 2] - stones[0] + 1) - N); // Move to left most
        return {low, high};
    }

private:
    int calculateLow(int low, int val) {
        return std::min(low, val);
    }
};

