class Solution {
public:
    std::vector<int> closestPrimes(int left, int right) {
        if (left == 1) left++;
        std::vector<bool> v(right + 1, true);
        for (int i = 2; i <= std::sqrt(right); i++) {
            if (v[i]) {
                for (int j = i * i; j <= right; j += i) {
                    v[j] = false;
                }
            }
        }
        int i = left;
        int j;
        int a = -1, b = -1, k = INT_MAX;
        while (i <= right) {
            if (v[i]) break;
            i++;
        }
        j = i;
        while (j <= right) {
            if (v[j]) {
                if (j - i < k) {
                    k = j - i;
                    a = i, b = j;
                }
                i = j;
            }
            j++;
        }
        return {a, b, b - a};
    }
};

class Solution {
public:
    int findPeakElement(vector<int>& nums) {
        int n = nums.size();
        if (n == 1) {
            return 0;
        }
        if (nums[0] > nums[1]) {
            return 0;
        }
        if (nums[n - 1] > nums[n - 2]) {
            return n - 1;
        }
        int left = 1;
        int right = n - 2;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (nums[mid] > nums[mid - 1] && nums[mid] > nums[mid + 1]) {
                return mid;
            } else if (nums[mid] > nums[mid - 1]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -1;
    }
};

