class Solution {
public:
    int lengthOfLIS(std::vector<int>& nums) {
        // Array to store the length of the longest increasing subsequence ending at each index
        std::vector<int> dp(nums.size(), 1);
        int maxLength = 1; // To store the maximum length of LIS found so far

        for (int i = 0; i < nums.size(); i++) {
            for (int j = 0; j < i; j++) {
                // Check if nums[i] can extend the subsequence ending at j
                if (nums[i] > nums[j]) {
                    if (dp[j] + 1 > dp[i]) {
                        dp[i] = dp[j] + 1; // Update the length of LIS ending at i
                    }
                }
            }
            maxLength = std::max(maxLength, dp[i]); // Update the maximum length
        }

        return maxLength;
    }
};

