class Solution {
public:
    std::vector<int> countsort(std::vector<int> &nums)
    {
        int n = nums.size();
        std::map<int, int> m;
        for (int i = 0; i < n; i++ )
            m[nums[i]]++;

        nums.clear();
        for (const auto &it : m)
        {
            int cnt = it.second;
            while (cnt--)
            {
                nums.push_back(it.first);
            }
        }
        return nums;
    }

    int maximumGap(std::vector<int> &nums)
    {
        int n = nums.size();
        if (n < 2)
            return 0;
        std::vector<int> sortednums = countsort(nums);

        int maxgap = 0;
        for (int i = 1; i < n; i++)
        {
            int currgap = sortednums[i] - sortednums[i - 1];
            maxgap = std::max(maxgap, currgap);
        }

        return maxgap;
    }
};

