class Solution {
    public int totalStrength(int[] strength) {
        int mod = 1000000007;

        int len = strength.length;

        long[] prefix = prefixSum(strength, len, mod);

        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(-1);

        long ans = 0;
        for(int i = 0; i < len; i++) {
            while(stack.peek() != -1 && strength[i] <= strength[stack.peek()]) {
                int mid = stack.pop();
                int left = stack.peek() + 1;
                int right = i - 1;

                int n = (mid - left);
                int t = (right - mid);

                long val = (1l * (1 + n) * (prefix[right + 2] - prefix[mid + 2]) + mod) % mod;
                val -= (1l * (1 + t) * (prefix[mid + 1] - prefix[left]) + mod) % mod;
                val *= strength[mid];

                ans += val;
                ans %= mod;
            }

            stack.push(i);
        }

        int right = len - 1;
        while(stack.peek() != -1) {
            int mid = stack.pop();
            int left = stack.peek() + 1;

            int n = (mid - left);
            int t = (right - mid);

            long val = (1l * (1 + n) * (prefix[right + 2] - prefix[mid + 1]) + mod) % mod;
            val -= (1l * (1 + t) * (prefix[mid + 1] - prefix[left]) + mod) % mod;
            val *= strength[mid];

            ans += val;
            ans %= mod;
        }

        return (int)((ans + mod) % mod);
    }

    private long[] prefixSum(int[] strength, int len, int mod) {
        long[] prefix = new long[len + 1];

        for(int i = 0; i < len; i++) {
            prefix[i + 1] = prefix[i] + strength[i];
        }

        long[] doublePrefix = new long[len + 2];
        for(int i = 0; i <= len; i++) {
            doublePrefix[i + 1] = (doublePrefix[i] + prefix[i]) % mod;
        }

        return doublePrefix;
    }
}

import java.io.PrintWriter;
import java.util.NavigableSet;
import java.util.Scanner;
import java.util.TreeSet;


public class C {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int m = in.nextInt();
        TreeSet<Integer> ts = new TreeSet<Integer>();
        for (int i = 0; i < n; i++) {
            ts.add(i + 1);
        }
        int[] mas = new int[n + 1];
        for (int i = 0; i < m; i++) {
            int l = in.nextInt();
            int r = in.nextInt();
            int k = in.nextInt();
            NavigableSet<Integer> sub = ts.subSet(l, true, r, true);
            while (!sub.isEmpty() && sub.first() != k) { // Fixed condition error
                int cur = sub.pollFirst();
                if (cur != k) {
                    mas[cur] = k;
                }
            }
            ts.add(k);
        }
        for (int i = 1; i <= n; i++) {
            out.print(mas[i]);
            out.print(" ");
        }

        out.close();
    }
}

class Solution {
    public int maxSumSubmatrix(int[][] matrix, int k) {
        int result = Integer.MIN_VALUE;

        for(int left = 0; left < matrix[0].length; left++){

            int[] rSum = new int[matrix.length];

            for(int right = left; right < matrix[0].length; right++){
                for(int row = 0; row < matrix.length; row++)
                    rSum[row] += matrix[row][right];

                TreeSet<Integer> set = new TreeSet<>();

                set.add(0);
                int cs = 0;

                for(int a: rSum){
                    cs += a;

                    Integer target = set.ceiling(cs - k);

                    if(target != null)
                        result = Math.max(result, cs - target);
                    set.add(cs);
                }
            }
        }
        return result;
    }
}

class Solution {
    public boolean judgeCircle(String moves) {
        int[] point = {0, 0};
        int[][] move = new int[][]{{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (char m : moves.toCharArray()) {
            int ind = 0;
            switch (m) {
                case 'U':
                    ind = 0;
                    break;
                case 'D':
                    ind = 1;
                    break;
                case 'L':
                    ind = 2;
                    break;
                case 'R':
                    ind = 3;
                    break;
            }
            point[0] += move[ind][0];
            point[1] += move[ind][1];
        }
        return point[0] == 0 && point[1] == 0;
    }
}

class Solution {
    public int minMoves(int[] a, int k) {
		int n = a.length;
		ArrayList<Integer> oneInd = new ArrayList<>();
		for (int i = 0; i < n; i++)
			if (a[i] == 1)
				oneInd.add(i);
		int prfsm[] = new int[oneInd.size()];
		for (int i = 0; i < oneInd.size(); i++) {
			prfsm[i] = oneInd.get(i) + (i == 0 ? 0 : prfsm[i - 1]);
		}
		int ans = Integer.MAX_VALUE;
		int left = 0, right = k - 1;
		while (right < oneInd.size()) {
			if (k % 2 == 1) {
				int medianInd = left + (k + 1) / 2 - 1;
				int rad = medianInd - left;
				int res = (prfsm[right] - prfsm[medianInd])
						- ((medianInd == 0 ? 0 : prfsm[medianInd - 1]) - (left == 0 ? 0 : prfsm[left - 1])) - rad * rad;
				ans = Math.min(ans, res);
			} else {
				int medianInd = left + (k + 1) / 2 - 1;
				int rad = medianInd - left;
				int res = (prfsm[right] - prfsm[medianInd])
						- ((medianInd == 0 ? 0 : prfsm[medianInd - 1]) - (left == 0 ? 0 : prfsm[left - 1]))
						- oneInd.get(medianInd) - rad * rad;
				ans = Math.min(ans, res);
			}
			left++;
			right++;
		}
		return ans;
	}
}

class Solution {
    double possible = 0.0;
    double valid = 0.0;

    public double getProbability(int[] balls) {
        int[] first = new int[balls.length];
        int[] second = new int[balls.length];
        dfs(balls, first, second, 0, 0, 0);
        return valid / possible;
    }

    private void dfs(int[] balls, int[] first, int[] second, int num1, int num2, int idx) {
        if (idx == balls.length) {
            if (num1 == num2) {
                double distrib = permFake(first) * permFake(second);
                possible += distrib;
                if (unique(first) == unique(second)) {
                    valid += distrib;
                }
            }
            return;
        }
        for (int b = 0; b <= balls[idx]; b++) {
            first[idx] = b;
            second[idx] = balls[idx] - b;
            dfs(balls, first, second, num1 + first[idx], num2 + second[idx], idx + 1);
        }
    }

    private int unique(int[] balls) {
        int unique = 0;
        for (int b: balls) {
            if (b > 0) {
                unique++;
            }
        }
        return unique;
    }

    private double permFake(int[] balls) {
        double ret = 1.0;
        for (int b: balls) {
            ret /= factorial(b);
        }
        return ret;
    }

    private int factorial(int n) {
        int ret = 1;
        while (n > 0) {
            ret *= n;
            n--;
        }
        return ret;
    }
}

