            dfs(balls, first, second, num1 + first[idx], num2 + second[idx], idx + 1);
        }
    }

    private double permFake(int[] arr) {
        int n = 0;
        for (int num : arr) {
            n += num;
        }
        return factorial(n) / (productOfFactorials(arr));
    }

    private double productOfFactorials(int[] arr) {
        double product = 1.0;
        for (int num : arr) {
            product *= factorial(num);
        }
        return product;
    }

    private int unique(int[] arr) {
        int count = 0;
        for (int num : arr) {
            if (num > 0) {
                count++;
            }
        }
        return count;
    }

    private int factorial(int n) {
        int ret = 1;
        while (n > 0) {
            ret *= n;
            n--;
        }
        return ret;
    }
}

